task apps_2930__summation(num: int) returns (r: int)
  requires num > 0
  ensures r == num * (num + 1) / 2
{
  r := 0;
  var i: int := 1;
  while i <= num
    invariant r == (i - 1) * i / 2
    invariant i >= 1 and i <= num + 1
    decreases num - i + 1
  {
    r := r + i;
    i := i + 1;
  }
}

